export const DIFFICULTIES={cadet:{name:'Cadet',budget:1.25,goal:.8,events:.6},standard:{name:'Flight director',budget:1,goal:1,events:1},expert:{name:'Expert',budget:.85,goal:1.2,events:1.4},sandbox:{name:'Sandbox',budget:1,goal:1,events:1}};
export const TEAM_ROLES=[{name:'Mission lead',icon:'✧',color:'#b7a0f3',responsibility:'Objective, schedule and budget',fields:['scenario','difficulty','days','teamSize','seed']},{name:'Systems engineer',icon:'⌬',color:'#9cdeb1',responsibility:'Structure, power and propellant',fields:['bus','array','battery','fuel']},{name:'Science officer',icon:'⌖',color:'#ed919d',responsibility:'Payload and observation schedule',fields:['payload','hours']},{name:'Flight & comms',icon:'⬡',color:'#edbd81',responsibility:'Orbit, launch vehicle and downlink',fields:['orbit','launcher','radio']}];
const n=(value,fallback,min,max)=>Number.isFinite(Number(value))?Math.max(min,Math.min(max,Number(value))):fallback;
const pick=(list,id,fallback)=>list.some(x=>x.id===id)?id:fallback;
const find=(list,id)=>list.find(x=>x.id===id);
const clamp=(v,min,max)=>Math.max(min,Math.min(max,v));
export function defaultPlan(id='climate'){const s=find(SCENARIOS,id)||SCENARIOS[0];return {version:1,scenario:s.id,difficulty:'standard',bus:'standard',array:s.id==='mars'?'large':'standard',battery:s.id==='mars'?'large':'standard',radio:s.id==='mars'?'deep':'standard',orbit:s.orbit,launcher:s.id==='mars'?'titan':s.id==='lunar'?'atlas':'swift',payload:s.id==='lunar'?['spectrometer','radar']:[...s.preferred],fuel:s.id==='mars'?140:s.id==='lunar'?85:60,days:s.days,hours:6,seed:2407,teamSize:1};}
export function sanitizePlan(input={}){if(!input||typeof input!=='object'||Array.isArray(input))input={};const d=defaultPlan(input.scenario);return {...d,scenario:pick(SCENARIOS,input.scenario,d.scenario),difficulty:Object.hasOwn(DIFFICULTIES,input.difficulty)?input.difficulty:d.difficulty,bus:pick(BUSES,input.bus,d.bus),array:pick(ARRAYS,input.array,d.array),battery:pick(BATTERIES,input.battery,d.battery),radio:pick(RADIOS,input.radio,d.radio),orbit:pick(ORBITS,input.orbit,d.orbit),launcher:pick(LAUNCHERS,input.launcher,d.launcher),payload:Array.isArray(input.payload)?[...new Set(input.payload.filter(id=>INSTRUMENTS.some(i=>i.id===id)))]:d.payload,fuel:n(input.fuel,d.fuel,10,250),days:Math.round(n(input.days,d.days,15,180)),hours:n(input.hours,d.hours,1,16),seed:Math.round(n(input.seed,d.seed,1,9999)),teamSize:Math.round(n(input.teamSize,1,1,4))};}
export function fieldOwner(field,teamSize){const i=TEAM_ROLES.findIndex(r=>r.fields.includes(field));return i<teamSize&&i>=0?i:0;}
export function evaluatePlan(input){const plan=sanitizePlan(input),scenario=find(SCENARIOS,plan.scenario),difficulty=DIFFICULTIES[plan.difficulty],bus=find(BUSES,plan.bus),array=find(ARRAYS,plan.array),battery=find(BATTERIES,plan.battery),radio=find(RADIOS,plan.radio),orbit=find(ORBITS,plan.orbit),launcher=find(LAUNCHERS,plan.launcher),payload=INSTRUMENTS.filter(i=>plan.payload.includes(i.id));
const total=(k)=>payload.reduce((s,i)=>s+i[k],0),mass=bus.mass+array.mass+battery.mass+radio.mass+total('mass')+plan.fuel,cost=bus.cost+array.cost+battery.cost+radio.cost+total('cost')+launcher.cost+plan.fuel*.06,capacity=launcher.capacity[orbit.id]||0,budget=scenario.budget*difficulty.budget,generated=array.power*scenario.solar*orbit.sun,load=bus.power+total('power')*plan.hours/24+radio.power*orbit.contact,powerMargin=generated-load,eclipseHours=orbit.period/60*(1-orbit.sun),eclipseRequired=(bus.power+total('power')*plan.hours/24)*eclipseHours,dataDaily=total('rate')/8*plan.hours*3600/1000,downlinkDaily=radio.rate/8*86400*orbit.contact*orbit.link/1000,fuelRequired=orbit.baseFuel+plan.days*orbit.burn,scienceDaily=payload.reduce((s,i)=>s+i.science*(scenario.weights[i.id]||.3),0)*plan.hours*orbit.coverage,target=scenario.goal*difficulty.goal;
const checks=[];const check=(level,code,title,why,fix)=>checks.push({level,code,title,why,fix});
if(orbit.body!==scenario.body)check('error','destination','Orbit reaches the wrong world',`${orbit.name} is around ${orbit.body}; the objective is at ${scenario.body}.`,'Choose an orbit around the mission destination.');
if(!capacity)check('error','route','Launcher cannot reach this orbit',`${launcher.name} has no supported ${orbit.name} injection in this model.`,'Choose a launcher with a payload rating for this orbit.');else if(mass>capacity)check('error','mass','Payload exceeds launch capacity',`${Math.round(mass)} kg exceeds the ${Math.round(capacity)} kg rating for this route.`,'Remove an instrument, choose lighter systems, or upgrade the launcher.');
if(cost>budget&&plan.difficulty!=='sandbox')check('error','budget','Mission exceeds the budget',`Development and launch cost ${cost.toFixed(1)} M credits; the limit is ${budget.toFixed(1)} M.`,'Reduce subsystem costs or use a cheaper compatible launcher.');
if(!payload.length)check('error','payload','No science instruments selected','A spacecraft without a payload cannot collect science.','Install at least one instrument relevant to the objective.');
if(plan.fuel<fuelRequired)check('error','fuel','Propellant does not cover the mission',`Injection and station keeping require ${fuelRequired.toFixed(1)} kg; only ${plan.fuel.toFixed(1)} kg is loaded.`,'Add propellant or shorten the mission, then recheck launch mass.');
if(plan.days>orbit.lifetime)check('error','lifetime','Orbit lifetime is too short',`${orbit.name} supports ${orbit.lifetime} days without additional lifetime engineering.`,'Shorten the planned mission or select a longer-lived orbit.');
if(powerMargin<0)check('warn','power','Average energy deficit',`Average generation is ${Math.round(generated)} W versus ${Math.round(load)} W demand. The battery will drain.`,'Increase solar area, reduce observation hours, or use fewer instruments.');else if(powerMargin<load*.25)check('warn','power-margin','Small power safety margin',`Only ${Math.round(powerMargin)} W remains for unexpected losses in sunlight.`,'Leave extra generation margin for solar storms.');
if(battery.capacity<eclipseRequired)check('warn','eclipse','Battery cannot span the eclipse',`The orbit needs about ${Math.round(eclipseRequired)} Wh during darkness, more than the ${battery.capacity} Wh pack.`,'Install a larger battery or reduce the payload duty cycle.');
if(dataDaily>downlinkDaily)check('warn','data','Data arrives faster than it can be sent',`${dataDaily.toFixed(2)} GB/day is generated but ${downlinkDaily.toFixed(2)} GB/day can be downlinked. Storage will fill.`,'Upgrade the antenna, reduce observation hours, or schedule downlink days.');
if(orbit.radiation>bus.hardening)check('warn','radiation','Radiation protection is limited','This orbit is harsher than the selected bus shielding. Health will decline during extended operations.','Use a hardened bus or leave extra lifetime and science margin.');
if(scienceDaily*plan.days<target)check('warn','science','Ideal science yield is below the objective',`Even without disruptions the payload yields ${Math.round(scienceDaily*plan.days)} points; the target is ${Math.round(target)}.`,'Choose instruments matched to the objective, observe longer, or extend the mission.');
if(plan.difficulty==='sandbox')check('info','sandbox','Budget constraint disabled','Sandbox allows experiments above the budget. Launch capacity, destination and fuel constraints still apply.','Compare this design with a budget-constrained mission when ready.');
return {plan,scenario,difficulty,bus,array,battery,radio,orbit,launcher,payload,mass,cost,budget,capacity,generated,load,powerMargin,eclipseHours,eclipseRequired,dataDaily,downlinkDaily,fuelRequired,scienceDaily,target,checks,errors:checks.filter(c=>c.level==='error'),warnings:checks.filter(c=>c.level==='warn'),valid:!checks.some(c=>c.level==='error')};}
export function createSimulation(input){const e=evaluatePlan(input);let seed=e.plan.seed;const random=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;};const offset=Math.floor(random()*4);const events=[{day:8+offset,duration:3,type:'solar',title:'Solar storm',detail:'Reduced sunlight and radio interference for three days.'},{day:22+offset,duration:4,type:'antenna',title:'Antenna calibration drift',detail:'Downlink capacity is halved for four days.'},{day:38+offset,duration:1,type:'impact',title:'Micrometeoroid strike',detail:'Shielding limits the damage to spacecraft health.'},{day:51+offset,duration:1,type:'leak',title:'Thruster valve leak',detail:'An unexpected maneuver consumes additional propellant.'}];return {evaluation:e,day:0,energy:e.battery.capacity,fuel:Math.max(0,e.plan.fuel-e.orbit.baseFuel),health:100,buffer:0,pendingScience:0,science:0,generatedData:0,sentData:0,lostData:0,uptime:0,brownoutDays:0,history:[],events,log:[],done:!e.valid,aborted:!e.valid,decisions:[],report:null};}
export function stepSimulation(state,policy='balanced'){if(state.done)return state;const e=state.evaluation;const {plan,orbit,bus,battery,radio,difficulty}=e;state.day++;if(!['balanced','observe','conserve','downlink'].includes(policy))policy='balanced';if(state.decisions.at(-1)?.policy!==policy)state.decisions.push({day:state.day,policy});let solar=1,link=1;let active=[];for(const event of state.events){if(event.day===state.day){state.log.push({...event});if(event.type==='impact')state.health-=Math.max(1,12-bus.hardening*5)*difficulty.events;if(event.type==='leak')state.fuel-=6*difficulty.events;}if(state.day>=event.day&&state.day<event.day+event.duration){active.push(event.title);if(event.type==='solar'){solar=1-.35*difficulty.events;link*=1-.45*difficulty.events;}if(event.type==='antenna')link*=.5;}}
const duty={balanced:1,observe:1.3,conserve:.45,downlink:.2}[policy],hours=Math.min(20,plan.hours*duty),payloadPower=e.payload.reduce((s,i)=>s+i.power,0),load=bus.power+payloadPower*hours/24+radio.power*orbit.contact*(policy==='downlink'?1.4:1),gen=e.generated*solar,eclipse=(bus.power+payloadPower*hours/24)*e.eclipseHours,dayDemand=load*24,available=gen*24+state.energy,energyFactor=clamp(available/dayDemand,0,1),eclipseFactor=clamp(battery.capacity/Math.max(1,eclipse),0,1),uptime=clamp(energyFactor*eclipseFactor*state.health/100,0,1);
state.energy=clamp(state.energy+(gen-load*energyFactor)*24,0,battery.capacity);if(uptime<.9)state.brownoutDays++;state.uptime+=uptime;
const newData=e.dataDaily*(hours/plan.hours)*uptime,newScience=e.scienceDaily*(hours/plan.hours)*uptime;state.generatedData+=newData;state.buffer+=newData;state.pendingScience+=newScience;const downlink=e.downlinkDaily*link*(policy==='downlink'?1.65:1)*Math.max(.1,energyFactor);const sent=Math.min(state.buffer,downlink),scienceSent=state.buffer>0?state.pendingScience*(sent/state.buffer):0;state.buffer-=sent;state.pendingScience-=scienceSent;state.science+=scienceSent;state.sentData+=sent;if(state.buffer>bus.storage){const lost=state.buffer-bus.storage;state.pendingScience*=bus.storage/state.buffer;state.buffer=bus.storage;state.lostData+=lost;}
state.fuel-=orbit.burn;if(Math.abs(state.fuel)<1e-9)state.fuel=0;state.health=clamp(state.health-Math.max(0,orbit.radiation-bus.hardening)*.07*difficulty.events,0,100);state.history.push({day:state.day,energy:state.energy,fuel:Math.max(0,state.fuel),health:state.health,buffer:state.buffer,science:state.science,power:uptime,policy,events:active});if(state.day>=plan.days||state.fuel<=0||state.health<=0){state.done=true;}return state;}
export function missionReport(state,approvals=[]){const e=state.evaluation,uptime=state.day?state.uptime/state.day:0,goalRatio=state.science/e.target,delivery=state.generatedData?state.sentData/state.generatedData:0,complete=state.day>=e.plan.days&&!state.aborted&&state.health>0&&state.fuel>=0,success=complete&&goalRatio>=1,teamRatio=e.plan.teamSize===1?1:approvals.slice(0,e.plan.teamSize).filter(Boolean).length/e.plan.teamSize;const categories={objectives:success?300:Math.round(120*Math.min(1,goalRatio)),science:Math.round(250*Math.min(1,goalRatio)),efficiency:Math.round(200*clamp((Math.max(0,1-e.cost/e.budget)*1.8+delivery+Math.max(0,state.fuel/e.plan.fuel))/3,0,1)),engineering:Math.round(150*uptime*state.health/100),collaboration:Math.round(100*teamRatio)};const score=Object.values(categories).reduce((a,b)=>a+b,0),reasons=[];if(e.errors.length)reasons.push(...e.errors.map(c=>({title:c.title,detail:c.why,tip:c.fix})));if(!state.aborted){reasons.push({title:goalRatio>=1?'Science objective achieved':'Science objective missed',detail:`${Math.round(state.science).toLocaleString()} / ${Math.round(e.target).toLocaleString()} points delivered to the ground. Science counts only after transmission.`,tip:goalRatio>=1?'Try a lighter or lower-cost design while keeping this science margin.':'Increase useful observation time, choose instruments matched to the objective, or improve downlink.'});if(state.lostData>.01)reasons.push({title:'Storage overflow lost science',detail:`${state.lostData.toFixed(1)} GB was discarded when the ${e.bus.storage} GB buffer filled.`,tip:'Install more storage, use a stronger antenna, or switch to downlink operations before the buffer fills.'});if(state.brownoutDays)reasons.push({title:'Power or health reduced observation time',detail:`${state.brownoutDays} days ran below 90% effective uptime. Average uptime: ${Math.round(uptime*100)}%.`,tip:'Check eclipse battery size and solar margin. Conserve operations during a solar storm.'});if(state.fuel<0||state.day<e.plan.days)reasons.push({title:'Propellant ran out early',detail:`Operations ended on day ${state.day} of ${e.plan.days}.`,tip:'Carry a propellant reserve above the minimum for unexpected maneuvers.'});if(!state.lostData&&state.brownoutDays===0)reasons.push({title:'Engineering margins protected the mission',detail:'The spacecraft kept its data buffer within capacity and maintained at least 90% effective uptime.',tip:'Compare lower-mass alternatives to see where those margins become too small.'});}
if(e.plan.teamSize>1)reasons.push({title:'Crew design review',detail:`${Math.round(teamRatio*e.plan.teamSize)} of ${e.plan.teamSize} participants approved this revision.`,tip:'Discuss mass, power, science and downlink together; editing a design invalidates earlier approvals.'});return {version:1,success,aborted:state.aborted,score,categories,science:state.science,target:e.target,uptime,delivery,days:state.day,plannedDays:e.plan.days,cost:e.cost,budget:e.budget,mass:e.mass,fuelRemaining:Math.max(0,state.fuel),health:state.health,lostData:state.lostData,reasons,events:state.log,decisions:state.decisions,plan:{...e.plan},model:'Simplified daily energy and data model. Not a real trajectory or mission certification.'};}
export function simulateMission(plan,policy='balanced',approvals=[]){const s=createSimulation(plan);while(!s.done)stepSimulation(s,policy);s.report=missionReport(s,approvals);return s;}
export function expeditionModifiers(input){const e=evaluatePlan(input);return {valid:e.valid,scenario:e.scenario.id,destination:e.scenario.body,speed:clamp(750/e.mass,.65,1.2),energyRegen:clamp(e.generated/Math.max(1,e.load),.55,1.5),captureRate:clamp(e.downlinkDaily/Math.max(.1,e.dataDaily),.65,1.3),fuelReserve:clamp((e.plan.fuel-e.fuelRequired)/e.plan.fuel*100+50,20,100),scienceBonus:Math.round(Math.min(300,e.scienceDaily*2)),difficulty:e.plan.difficulty};}
